#!/usr/bin/env python3
"""A compact, actual-render comparison of the local 023 terrain upgrade."""
from pathlib import Path
import json, hashlib
ROOT=Path(__file__).resolve().parents[2]
LIB=ROOT/'docs/design/ground-detail-023'
VIEWS={'city_delhi':'德里与北部平原','plain':'平原与丘陵近景','dunes':'塔克拉玛干沙地','everest':'珠峰与山麓','coast':'样区南缘与海岸','central':'丝路与高原','overview':'星球总览','city_panti':'盘橐城与区域边缘','everest_oblique':'珠峰山麓 · 30°斜向检查','plain_oblique':'平原坡谷 · 30°斜向检查'}
def main():
    report=json.loads((LIB/'terrain-report.json').read_text())
    options=''.join(f'<option value="{k}">{v}</option>' for k,v in VIEWS.items())
    html='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>丝路星球 · 雕刻分面地表</title><style>
*{box-sizing:border-box}body{margin:0;background:#f1efe5;color:#344438;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}main{max-width:1190px;margin:auto;padding:35px 32px 42px}.eyebrow{font-size:11px;letter-spacing:.15em;color:#718167}h1{font-size:clamp(28px,4vw,43px);font-weight:570;margin:17px 0 12px;line-height:1.4}.intro{color:#718067;font-size:14px;line-height:1.9;max-width:890px}.scope{font-size:12px;color:#586c50;background:#e4e8d8;border-left:3px solid #87956d;padding:12px 16px;margin:20px 0;line-height:1.9}.controls{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin:20px 0 12px}select,button{font:inherit;font-size:13px;border:1px solid #bfc8b3;background:#faf9f2;color:#435740;padding:9px 13px;border-radius:5px;cursor:pointer}.buttons{display:flex;gap:6px}button.active{background:#d9e2cb;border-color:#9cab89}a{color:#516d44;text-underline-offset:4px}a:focus-visible,button:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid #a9833e;outline-offset:3px}.comparison{position:relative;aspect-ratio:995/594;background:#182a32;overflow:hidden;border-radius:7px;--split:0%}.comparison img{position:absolute;left:0;top:calc(-62/594 * 100%);width:calc(1280/995 * 100%);height:auto;max-width:none}.before-wrap{position:absolute;inset:0;overflow:hidden;clip-path:inset(0 calc(100% - var(--split)) 0 0)}.divider{position:absolute;top:0;bottom:0;left:var(--split);width:2px;background:#f4edd0;display:none}.divider:after{content:'↔';position:absolute;top:48%;left:-17px;border-radius:50%;background:#f4edd0;width:36px;height:36px;display:grid;place-items:center;color:#3e563d}.badge{position:absolute;top:12px;background:#f6f0dbe8;font-size:11px;padding:6px 9px;border-radius:3px}.old{left:12px;visibility:hidden}.new{right:12px}.scrub{display:flex;gap:15px;align-items:center;margin:13px 0}.scrub label{font-size:12px;white-space:nowrap;color:#718167}input{width:100%;accent-color:#789164}.caption{font-size:12px;color:#718167;line-height:1.9}.detail{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;padding-top:22px;margin-top:27px;border-top:1px solid #cfd6c1}.detail h2{font-size:19px;font-weight:560;margin:10px 0}.detail span{font-size:11px;color:#9a825c}.detail p{font-size:12px;line-height:1.95;color:#718167}.files{margin-top:24px;border-top:1px solid #cfd6c1;padding-top:21px;font-size:12px;line-height:2.1}.files p{color:#718167;margin:8px 0}.subtle{font-size:11px;color:#7f8976}@media(max-width:720px){main{padding:26px 18px}.detail{grid-template-columns:1fr;gap:9px}.comparison{margin:0 -7px}.badge{font-size:10px}.buttons{gap:4px}button{padding:8px 10px}}
</style></head><body><main><div class="eyebrow">SILK ROAD / GROUND DETAIL 023</div><h1>把地形的棱面找回来。</h1><p class="intro">沿着山麓塑出连续脊线与侵蚀浅沟，沙地更硬朗，沟底保留少量柔和过渡。以真实起伏形成粗糙感。</p><div class="scope">左侧是上一轮过度平滑版，右侧是本轮雕刻分面版，镜头与照明保持一致。这仍是德里—珠峰—塔克拉玛干局部样区。页面显示固定地图区域裁切，完整实机原图可在下方打开。</div><div class="controls"><select id="view" aria-label="选择地表样区">OPTIONS</select><div class="buttons"><button data-mode="before">过平版</button><button data-mode="compare">拖动对照</button><button data-mode="after" class="active">分面新版</button></div></div><div class="comparison" id="comparison"><img id="after" src="previews/city_delhi-after.jpg" alt="德里地表分面新版实际画面"><div class="before-wrap"><img id="before" src="previews/city_delhi-smooth.jpg" alt="德里地表过平版实际画面"></div><div class="divider" id="divider"></div><span id="old-label" class="badge old">过平版</span><span id="new-label" class="badge new">分面新版</span></div><div class="scrub"><label for="split">前后对照</label><input id="split" type="range" min="0" max="100" value="0" aria-label="前后画面分界"></div><div class="caption"><span id="caption">德里与北部平原</span> · Godot 实际渲染 · <a id="before-full" href="previews/city_delhi-smooth.jpg" target="_blank" rel="noopener">完整原图：过平版</a> · <a id="after-full" href="previews/city_delhi-after.jpg" target="_blank" rel="noopener">分面新版</a></div><section class="detail"><article><span>01 / 地表形体</span><h2>沟脊有大小层次</h2><p>在宽缓坡面上增加有方向的脊线、沟槽和次级凹凸。相邻折面沿地势成组，形体有清楚的厚度。陆地主网格为TRI_COUNT个三角。</p></article><article><span>02 / 明暗与地色</span><h2>分面跟着地势走</h2><p>干沙脊与岩性坡肩保留硬朗受光，草坡适度分面，沟底稍柔和。地色配合起伏，避免满地随机三角色差。</p></article><article><span>03 / 景点与地图</span><h2>放回同一片地表</h2><p>沿用现有精修景点，按新的地势调整落地高度与脚坡，让山麓和小地物承接周围地表。河流端部等既有问题另行记录。</p></article></section><section class="files"><a href="source/ground.blend" download>下载 Blender 地表源文件</a> · <a href="exports/ground.glb" download>下载 GLB</a> · <a href="README.md">样区说明与检查结果</a> · <a href="../terrain-transition-022/index.html">上一版景点过渡</a><p>可旋转 Godot 样板：仓库内双击 open-ground.command，可对照最初地表与本轮分面新版。网页的左侧单独保留上一轮过平版本。</p><div class="subtle">局部升级预览，未替换正式地图。静态画面对照不代替全局动态遮挡或跨设备性能验收。</div></section></main><script>
const titles=TITLES;const view=document.querySelector('#view'),split=document.querySelector('#split'),comparison=document.querySelector('#comparison');
function setSplit(value){split.value=value;comparison.style.setProperty('--split',value+'%');document.querySelector('#divider').style.display=value>0&&value<100?'block':'none';document.querySelector('#old-label').style.visibility=value>0?'visible':'hidden';document.querySelector('#new-label').style.visibility=value<100?'visible':'hidden';document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===(value===100?'before':value===0?'after':'compare')))}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setSplit(b.dataset.mode==='before'?100:b.dataset.mode==='after'?0:50));split.oninput=()=>setSplit(Number(split.value));view.onchange=()=>{for(const phase of ['before','after']){document.querySelector('#'+phase).src='previews/'+view.value+'-'+(phase==='before'?'smooth':'after')+'.jpg';document.querySelector('#'+phase).alt=titles[view.value]+(phase==='before'?'过平版':'分面新版')+'实际画面';document.querySelector('#'+phase+'-full').href='previews/'+view.value+'-'+(phase==='before'?'smooth':'after')+'.jpg'}document.querySelector('#caption').textContent=titles[view.value]};
</script></body></html>'''
    revision=hashlib.sha256(b''.join(hashlib.sha256(p.read_bytes()).digest() for p in sorted((LIB/'previews').glob('*.jpg')))).hexdigest()[:12]
    html=html.replace('.jpg"', '.jpg?v='+revision+'"').replace("+'.jpg'", "+'.jpg?v="+revision+"'")
    (LIB/'index.html').write_text(html.replace('OPTIONS',options).replace('TRI_COUNT',f"{report['triangles']:,}").replace('TITLES',json.dumps(VIEWS,ensure_ascii=False)))
    print('ground023 gallery ready')
if __name__=='__main__':main()
